1: // DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
2: // "Step 1 Hop ->" trace — one hop per call, running across the same
3: // network/LB/queue/cache machinery the crowd uses (it does not fake a
4: // shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
5: // (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
6: // backend's cache-aside lookup and the HTTP response emission split into
7: // two hops so the learner can watch Cache 10.20 answer, then the backend
8: // emit); 7 in Stage 4 (the Database hop inserted after the cache check —
9: // the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
10: // 10.31, or the SKIP a warm cache HIT earns).
11: //
12: // The machine owns the trace state and hop transitions; the engine owns
13: // the clock, the served-exchange record, and browser delivery, handed in
14: // as the four callbacks below.
15: //
16: // CHECKS: an out-of-range stage fails loud at construction instead of
17: // building a trace that can never advance.
18: export function createTraceMachine({
19:   stage,
20:   serverAddress,
21:   servers,
22:   lb = null,
23:   network,
24:   cache = null,
25:   database = null,
26:   workerQueue = null,
27:   bumpTick,
28:   getTick,
29:   onServe,
30:   onFinish,
31: }) {
32:   if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5) {
33:     throw new Error(`trace: stage must be 1, 2, 3, 4, or 5, got ${stage}`);
34:   }
35:   let trace = freshTrace();
36:   let served = null; // the drained response record, held between hops 4/6 and 5/6
37: 
38:   function freshTrace() {
39:     return {
40:       hop: 0,
41:       method: 'GET',
42:       path: '/about',
43:       from: '10.2',
44:       request: 'GET /about',
45:       targetServer: null,
46:       cacheStatus: null,
47:       dbOp: null,
48:       dbStale: false,
49:       response: null,
50:       status: null,
51:       body: null,
52:       routeId: null,
53:     };
54:   }
55: 
56:   // Serve from the front of the target's queue until the trace's own
57:   // request (isYou) comes back, or the queue runs dry this tick.
58:   function drainUntilYou(targetServer) {
59:     for (;;) {
60:       const batch = targetServer.step(getTick());
61:       const you = batch.find((item) => item.isYou);
62:       if (you || batch.length === 0) return you;
63:     }
64:   }
65: 
66:   function backendFor(targetAddress) {
67:     return servers.find((s) => s.address === targetAddress) ?? servers[0];
68:   }
69: 
70:   function serve(you) {
71:     trace.response = you.response;
72:     trace.status = you.status;
73:     trace.body = you.body;
74:     trace.routeId = you.routeId;
75:     onServe(you);
76:   }
77: 
78:   // Final hop: the rendered response lands on the browser the trace
79:   // originated from (the engine routes it into the right browser state).
80:   function finish(toAddress) {
81:     onFinish({
82:       from: trace.from ?? '10.2',
83:       to: toAddress,
84:       request: trace.request,
85:       response: trace.response,
86:     });
87:   }
