95:       if (trace.hop === 0 || trace.hop >= finalHop) {
96:         const request = `${method} ${path}`;
97:         trace = {
98:           hop: 1,
99:           method,
100:           path,
101:           from,
102:           request,
103:           targetServer: stage === 1 ? serverAddress : null,
104:           cacheStatus: null,
105:           dbOp: null,
106:           dbStale: false,
107:           response: null,
108:           status: null,
109:           body: null,
110:           routeId: null,
111:         };
112:         served = null;
113:         frame = `${from} -> ${serverAddress} | ${request}`;
114:       } else if (stage === 1 && trace.hop === 1) {
115:         trace.hop = 2;
116:         const atTick = bumpTick();
117:         network.deliverToQueue({
118:           id: `you:${atTick}`,
119:           from: trace.from,
120:           to: serverAddress,
121:           request: trace.request,
122:           atTick,
123:           isYou: true,
124:         });
125:         frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
