167:         trace.hop = 4;
168:         const backend = backendFor(trace.targetServer);
169:         served = drainUntilYou(backend);
170:         if (served) {
171:           trace.cacheStatus = served.cacheStatus ?? null;
172:           frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
173:         }
174:       } else if (stage === 3 && trace.hop === 4) {
175:         trace.hop = 5;
176:         if (served) {
177:           serve(served);
178:           frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
179:         }
180:       } else if (stage === 3 && trace.hop === 5) {
181:         trace.hop = 6;
