```js
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritativeConsults = 0;
  let nxAnswers = 0;
  let lastLookup = null;

  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) cache.delete(entry.name);
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      // Hit inside ttlTicks: the ledger answers; the authoritative table is
      // not consulted.
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', name, target: entry.target, source: 'cache' };
    }
    const target = authoritative.get(name) ?? null;
    authoritativeConsults += 1;
    if (target === null) {
      nxAnswers += 1;
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX', name };
    }
    cache.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'AUTH', target, atTick: currentTick };
    return { status: 'OK', name, target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritativeConsults,
      nxAnswers,
      authoritative: Object.fromEntries(authoritative),
      cache: [...cache.values()].map((e) => ({ name: e.name, target: e.target, expiresAtTick: e.expiresAtTick, ttlRemaining: e.expiresAtTick - currentTick })),
      lastLookup,
    };
  }

  return { get address() { return address; }, evictExpired, lookup, snapshot };
}
