```js
// trace-stage6.js
// DOCUMENTS: the Stage 6 DNS prefix — the two hosted-path hops the browser
// spends resolving a host through DNS before the Stage 5 request chain
// takes over. The ask hop performs the real resolver lookup (cache ledger
// with tick TTL); the answer hop narrates the record or ends the trace on
// NX (no GET is emitted for an unresolved name).
export function splitHostPath(path = '/') {...}

export function createDnsPrefix({ dns, getTick, onFinish }) {
  let record = null;
  return {
    // Hop 1: the browser asks; the resolver lookup runs now and the record
    // is held for the answer hop.
    ask({ from, host }) {
      record = dns ? dns.lookup(host, getTick()) : { status: 'NX', name: host };
      return `${from} -> ${dns.address} | ask ${host}`;
    },
    // Hop 2: the answer. Returns { frame, nx, target, source }.
    answer({ from }) {
      if (record.status === 'NX') {
        onFinish({ from: dns.address, to: from, request: ???, response: 'NX no record' });
        return { frame: `${dns.address} -> ${from} | NX no record`, nx: true };
      }
      return { frame: `${dns.address} -> ${from} | OK ${record.name} is ${record.target}`, target: record.target, source: record.source };
    },
  };
}
```

