// DOCUMENTS: the Stage 6 component — an authoritative resolver at mini-IP
// 10.60 that mirrors the Cache's tick-TTL ledger pattern: the authoritative
// table is consulted only on a miss (or an expired entry), and a hit inside
// ttlTicks is answered from the cache ledger with its own counter. Unknown
// names answer NX — the browser renders the NX card, and no GET is ever
// emitted for an unresolved name. Deterministic by construction: no clock,
// no RNG — time arrives as the `currentTick` argument, the same way the
// Cache keeps time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration, like cache.js).
const MINI_IP = /^\d+\.\d+$/;

export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // The authoritative table lives in-component; Stage 6b adds a CDN name.
  const authoritative = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritativeConsults = 0;
  let nxAnswers = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry, the
  // same rule the Cache ledger uses.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) {
        cache.delete(entry.name);
      }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      // Cache-branch answer: the ledger replies and the authoritative
      // table is not consulted — cachedHits is the only counter that moves.
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', name, target: entry.target, source: 'cache' };
    }
    // Miss (or expired entry already evicted above): consult the table.
    authoritativeConsults += 1;
    const target = authoritative.get(name) ?? null;
    if (target === null) {
      nxAnswers += 1;
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX', name };
    }
    cache.set(name, {
      name,
      target,
      cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks,
    });
    lastLookup = { name, status: 'AUTH', target, atTick: currentTick };
    return { status: 'OK', name, target, source: 'authoritative' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritativeConsults,
      nxAnswers,
      lastLookup,
      authoritative: Object.fromEntries(authoritative),
      cache: [...cache.values()].map((entry) => ({
        name: entry.name,
        target: entry.target,
        cachedAtTick: entry.cachedAtTick,
        expiresAtTick: entry.expiresAtTick,
        ttlRemaining: entry.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a router that joins two network
// instances on different subnets (10.x and 20.x). A cross-subnet frame
// takes exactly one router hop: the sending network sees the destination
// subnet differs from its own, hands the frame to `route()`, and the router
// delivers it into the destination network — one `routed` counter step, no
// extra hops. Same-subnet sends never touch the router and are unchanged.
// Nothing lives in subnet 20 in Stage 6a besides the router's own presence,
// so a send to an unregistered 20.x host fails loud from the destination
// network's resolve (DL-1, mirroring network.js).
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP on either side, and both sides sitting on the same subnet.
const MINI_IP = /^\d+\.\d+$/;

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (leftAddress.split('.')[0] === rightAddress.split('.')[0]) {
    throw new Error(
      `router: left and right sides must sit on different subnets (${leftAddress}, ${rightAddress})`,
    );
  }
  let routed = 0;
  let lastFrame = null;
  let rightNetwork = null;

  // One router hop: the frame exits the left side and enters the right
  // subnet's network instance, where normal resolve rules apply — so
  // unregistered hosts (20.9) fail loud right here.
  function route({ from, to, request }) {
    if (!rightNetwork) {
      throw new Error('router: no right-side network attached');
    }
    routed += 1;
    lastFrame = `${from} -> ${leftAddress} -> ${to} | ${request} (1 router hop)`;
    const record = rightNetwork.send({ from, to, request });
    return { ...record, viaRouter: leftAddress };
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    // Wires both networks: the sending network learns its cross-subnet
    // router; the router's own right side answers in subnet 20 (the only
    // reachable 20.x target in 6a — Stage 6b occupies it with the CDN edge).
    join(leftNetwork, networkOnRight) {
      rightNetwork = networkOnRight;
      leftNetwork.attachRouter(this);
      networkOnRight.registerServer(rightAddress, {
        handleRequest: () => `200 pong from ${rightAddress}`,
      });
    },

    route,

    snapshot() {
      return { leftAddress, rightAddress, routed, lastFrame };
    },
  };
}

