const MINI_IP = /^\d+\.\d+$/;

// `subnet` names this network's own subnet ("10" by default, today's
// behavior); a `router` attached via attachRouter carries cross-subnet
// frames — exactly one router hop — into the destination network. With no
// router attached a cross-subnet destination resolves the old way and fails
// loud when unregistered, so today's send contract is unchanged.
export function createNetwork({ subnet = '10' } = {}) {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    // Called by the router's join(): only a router attachment turns on
    // cross-subnet sends; nothing about same-subnet traffic changes.
    attachRouter(attached) {
      router = attached;
    },

    resolve,

    send({ from, to, request }) {
      validate(from);
      if (router && MINI_IP.test(to) && to.split('.')[0] !== subnet) {
        return router.route({ from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
