// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
// backend's cache-aside lookup and the HTTP response emission split into
// two hops so the learner can watch Cache 10.20 answer, then the backend
// emit); 7 in Stage 4 (the Database hop inserted after the cache check —
// the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
// 10.31, or the SKIP a warm cache HIT earns).
//
// Stage 6 branches on host syntax: a hosted URL (`example.com/about`) pays
// a DNS ask + answer hop first (the trace-stage6 prefix, resolved by the
// real dns.js ledger), then rides the Stage 5 chain shifted +2; a plain
// path never touches DNS and keeps the Stage 5 story byte-identical; an NX
// answer ends the trace at hop 2 with no GET emitted.
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance, and a Stage 6 machine without a
// dns resolver is rejected for the same reason.
import { createDnsPrefix, splitHostPath } from './trace-stage6.js';

export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
  onUnresolved = null,
}) {
  if (!Number.isInteger(stage) || stage < 1 || stage > 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  if (stage === 6 && !dns) {
    throw new Error('trace: stage 6 needs a dns resolver for hosted paths');
  }
  const dnsPrefix = createDnsPrefix({ dns, getTick, onFinish: onUnresolved ?? onFinish });
  let trace = freshTrace();
  let served = null; // the drained response record, held between hops 4/6 and 5/6

  function freshTrace({ method = 'GET', path = '/about', from = '10.2', targetServer = null } = {}) {
    const split = splitHostPath(path);
    return {
      hop: 1,
      method,
      path,
      from,
      request: `${method} ${path}`,
      targetServer,
      hosted: split.hosted,
      host: split.host,
      resolvedPath: split.path,
      dnsTarget: null,
      dnsSource: null,
      nx: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
  }

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const split = splitHostPath(path);
      const hosted = stage === 6 && split.hosted;
      // The final hop depends on the path shape: hosted = the Stage 5 chain
      // plus 2 DNS hops; NX ends at the answer hop; host-less = 8, the
      // Stage 5 story unchanged.
      const finalHop = () =>
        stage !== 6
          ? stage === 5
            ? 8
            : stage === 4
              ? 7
              : stage === 3
                ? 6
                : stage === 2
                  ? 5
                  : 4
          : trace.nx
            ? 2
            : trace.hosted
              ? 10
              : 8;
      // The Stage 2-5 chain runs in chain-space hops: a hosted Stage 6
      // trace rides it with its hop shifted +2 (the DNS prefix came first).
      const inChain = stage === 6 && trace.hosted && trace.hop >= 3;
      const eStage = stage === 6 ? 5 : stage;
      const hop = inChain ? trace.hop - 2 : trace.hop;
      const setHop = (chainHop) => {
        trace.hop = inChain ? chainHop + 2 : chainHop;
      };
      let frame = null;
      if (trace.hop === 0 || trace.hop >= finalHop()) {
        trace = freshTrace({ method, path, from, targetServer: stage === 1 ? serverAddress : null });
        served = null;
        if (hosted) {
          // Hop 1/10: the browser asks DNS 10.60 to resolve the host; the
          // resolver lookup runs now and its record is held for the answer.
          frame = dnsPrefix.ask({ from, host: trace.host });
        } else {
          frame = `${from} -> ${serverAddress} | ${trace.request}`;
        }
      } else if (stage === 1 && hop === 1) {
        setHop(2);
        const atTick = bumpTick();
        network.deliverToQueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.request,
          atTick,
          isYou: true,
        });
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) into queue`;
      } else if (stage === 1 && hop === 2) {
        setHop(3);
        const you = drainUntilYou(servers[0]);
        if (you) {
          serve(you);
          frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
        }
      } else if (stage === 1 && hop === 3) {
        setHop(4);
        finish(serverAddress);
      } else if (stage === 6 && trace.hosted && trace.hop === 1) {
        // Hop 2/10: the resolver answer. NX ends the trace here — the
        // browser renders the NX card and no GET is emitted.
        trace.hop = 2;
        const answer = dnsPrefix.answer({ from: trace.from });
        if (answer.nx) {
          trace.nx = true;
        } else {
          trace.dnsTarget = answer.target;
          trace.dnsSource = answer.source;
        }
        frame = answer.frame;
      } else if (stage === 6 && trace.hosted && trace.hop === 2) {
        // Hop 3/10: with the host resolved the browser emits the GET with
        // the resolved target; the Stage 5 chain takes over from here.
        trace.hop = 3;
        trace.request = `${trace.method} ${trace.resolvedPath}`;
        frame = `${trace.from} -> ${serverAddress} | ${trace.request}`;
      } else if (hop === 1) {
        setHop(2);
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
      } else if (hop === 2) {
        setHop(3);
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.request,
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${trace.request}) queued`;
      } else if (eStage === 2 && hop === 3) {
        setHop(4);
        const backend = backendFor(trace.targetServer);
        const you = drainUntilYou(backend);
        if (you) {
          serve(you);
          frame = `${backend.address} -> ${trace.from} | ${you.response}`;
        }
      } else if (eStage === 2 && hop === 4) {
        setHop(5);
        finish(trace.targetServer ?? serverAddress);
      } else if (eStage === 3 && hop === 3) {
        // Hop 4/6: the target backend checks Cache and serves the queued
        // request; the response record is held one hop so the learner sees
        // the cache lookup before the response leaves the backend.
        setHop(4);
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.resolvedPath})`;
        }
      } else if (eStage === 3 && hop === 4) {
        setHop(5);
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
        }
      } else if (eStage === 3 && hop === 5) {
        setHop(6);
        finish(trace.targetServer ?? serverAddress);
      } else if (eStage === 4 && hop === 3) {
        // Hop 4/7: the target backend checks Cache and serves the queued
        // request (a POST write-through carries cacheStatus INVALIDATE);
        // the response record is held so the learner watches the cache
        // lookup, then the database hop.
        setHop(4);
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.resolvedPath})`;
        }
      } else if (eStage === 4 && hop === 4) {
        // Hop 5/7: the database hop — hop 6's WRITE landed on Primary
        // 10.30 (replication queued toward 10.31), hop 5's SELECT read
        // Replica 10.31 fresh or stale, and a warm cache HIT skips the
        // database entirely.
        setHop(5);
        if (served) {
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.resolvedPath} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.resolvedPath} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.resolvedPath} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (eStage === 4 && hop === 5) {
        setHop(6);
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (eStage === 4 && hop === 6) {
        setHop(7);
        finish(trace.targetServer ?? serverAddress);
      } else if (eStage === 5 && hop === 3) {
        // Hop 4/8: an async POST /jobs enqueues to WorkerQueue 10.40; other
        // requests narrate the cache/database hop they actually took (the
        // Stage 4 story) — no phantom async jobs on GET traces (DL-4).
        setHop(4);
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
