parseResponse(raw) {
  const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
  // Numeric statuses parse to numbers; a non-numeric status token (the
  // DNS "NX no record" answer) is kept verbatim so the viewport badge
  // can read "NX" instead of a fabricated NaN.
  const status = /^\d+$/.test(statusToken) ? Number(statusToken) : statusToken;
  return { status, body: bodyParts.join(' ') };
},

