import { createRng } from './rng.js';
import { createNetwork } from './network.js';
import { createBrowser } from './browser.js';
import { createWebServer } from './webserver.js';
import { createLoadBalancer } from './loadbalancer.js';
import { createCache } from './cache.js';
import { createDatabase } from './database.js';
import { createWorkerQueue } from './queue.js';
import { createDns } from './dns.js';
import { createRouter } from './router.js';
import { createUsers } from './users.js';
import { createTraceMachine } from './trace.js';

export function createEngine({
  seed = 42,
  users = 5,
  serviceRate = 4,
  arrivalProb = 0.5,
  serverAddress = '10.1',
  stage = 1,
  backendAddresses = ['10.11', '10.12'],
  ttlTicks = 10,
  cacheAddress = '10.20',
  replicationLagTicks = 3,
  dbPrimaryAddress = '10.30',
  dbReplicaAddress = '10.31',
  workerQueueAddress = '10.40',
  workerAddress = '10.41',
  jobDurationTicks = 2,
  dnsAddress = '10.60',
  dnsTtlTicks = 300,
  routerLeftAddress = '10.65',
  routerRightAddress = '20.1',
} = {}) {
  if (typeof arrivalProb !== 'number' || arrivalProb < 0 || arrivalProb > 1) {
    throw new Error(`engine: arrivalProb must be within [0, 1], got ${arrivalProb}`);
  }
  if (!Number.isInteger(stage) || stage < 1 || stage > 6) {
    throw new Error(`engine: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  const rng = createRng(seed);
  const network = createNetwork();
  const cache = stage >= 3 ? createCache({ address: cacheAddress, ttlTicks }) : null;
  const database =
    stage >= 4
      ? createDatabase({
          primaryAddress: dbPrimaryAddress,
          replicaAddress: dbReplicaAddress,
          replicationLagTicks,
        })
      : null;
  const workerQueue =
    stage >= 5
      ? createWorkerQueue({
          address: workerQueueAddress,
          workerAddress,
          jobDurationTicks,
        })
      : null;
  // Stage 6: the DNS resolver (10.60, tick-TTL ledger) and the cross-subnet
  // Router joining this 10.x network with the 20.x one — the router's own
  // right side (20.1) is the only reachable 20.x target in 6a.
  const dns = stage >= 6 ? createDns({ address: dnsAddress, ttlTicks: dnsTtlTicks }) : null;
  const wanNetwork = stage >= 6 ? createNetwork({ subnet: '20' }) : null;
  const router =
    stage >= 6
      ? createRouter({ leftAddress: routerLeftAddress, rightAddress: routerRightAddress })
      : null;
  if (router) router.join(network, wanNetwork);

