input.content:
// DOCUMENTS: the Stage 6 node cards — #node-dns (resolver 10.60 with its
// lookup/hit counters and live resolver-cache rows) and #node-router (the
// cross-subnet gateway card with the `10.65 ⇄ 20.1` ip-chip and routed
// counter). Built in js rather than panel.html because that page sits at
// its 550-line cap (the teaching drawer set the precedent); behavior stays
// addEventListener-only and all content comes from textContent/attributes —
// no inline styles, no innerHTML (AGENTS.md CSP rule). panel.js runs this
// at boot, before the .node-card / .comp-tab bindings, so the standard
// selection and inspector wiring picks the cards up unchanged.
import { COMPONENT_SOURCE } from './inspector-source.js';

const IP_CHIP = { dns: '10.60', router: '10.65 ⇄ 20.1' };
const SUBTITLES = {
  dns: ['DNS', 'resolver · tick-TTL ledger'],
  router: ['Router', 'cross-subnet gateway'],
};

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function buildCard(component) {
  const card = el('article', 'node-card');
  card.id = `node-${component}`;
  card.dataset.testid = `node-${component}`;
  card.dataset.component = component;
  card.hidden = true; // revealed by render-stage on Stage 6
  const head = el('header', 'node-head');
  const name = el('div', 'node-name');
  name.append(
    el('span', 'role-name', SUBTITLES[component][0]),
    el('span', 'node-subtitle', SUBTITLES[component][1]),
  );
  head.append(name, el('span', 'ip-chip', IP_CHIP[component]), el('span', 'code-chip', '</> Code'));
  card.append(head);
  if (component === 'dns') {
    card.append(
      el('p', 'mono last-frame', 'Lookups: 0 · Cached hits: 0 · TTL: 300t'),
      el('ul', 'route-list'),
    );
  } else {
    card.append(el('p', 'mono last-frame', 'Routed: 0 · 10.65 ⇄ 20.1'));
  }
  return card;
}

// CHECKS: the card ids, data-testid anchors, stats/entries element ids, and
// the inspector tabs all come from the COMPONENT_SOURCE registry keys — a
// registry entry without its card (or vice versa) is a wiring defect caught
// by the Stage 6 e2e pins.
export function initStage6Nodes() {
  const world = document.getElementById('orrery-world');
  for (const component of Object.keys(COMPONENT_SOURCE)) {
    if (!document.getElementById(`node-${component}`)) {
      world.append(buildCard(component));
    }
  }
  // The inspector tabs derive from the same registry, replacing panel
  // html's static button list (the page sits at its 550-line cap).
  const tabHost = document.querySelector('.comp-tabs');
  if (tabHost && tabHost.children.length === 0) {
    for (const key of Object.keys(COMPONENT_SOURCE)) {
      const tab = el('button', 'comp-tab', key);
      tab.type = 'button';
      tab.dataset.select = key;
      tabHost.append(tab);
    }
  }
}

