// Single hop of the trace; the engine moves the request one stage per call,
// originating from whichever browser is currently expanded on Ring 3.
function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  // The hop total is path-shape-aware on Stage 6 (hosted = 10, NX = 2,
  // host-less = 8) and pinned per stage everywhere else.
  const totalHops = totalHopsFor(snapshot.stage, snapshot.trace);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

// A trace run is complete when its hop reaches the path-shape-aware total:
// a hosted Stage 6 trace lands on hop 10/10, an NX trace ends at hop 2/2
// (no GET), and every other stage keeps its pinned count.
const traceComplete = (snapshot) =>
  snapshot.trace.hop >= totalHopsFor(snapshot.stage, snapshot.trace);

$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  const iv = setInterval(() => {
    if (traceComplete(stepOneHop())) clearInterval(iv);
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  for (let i = 0; i < 12; i += 1) {
    if (traceComplete(stepOneHop())) break;
  }
});

