      'Hop 5/8: WebServer (10.11) -> "200 This is the about page" (cache MISS)',
    );
    expect(hostless(6)).toBe('Hop 6/8: Network delivers 200 response to 10.2');
    expect(hostless(7)).toBe('Hop 7/8: Browser (10.2) received and displayed 200');
    expect(hostless(8)).toBe('Hop 8/8: Worker (10.41) idle — no async jobs in this trace');
    expect(hostless(9)).toBe('Idle — type a path and click Go or Step 1 Hop ->');
    // The totals agree with the trace machine's shape contract.
    expect(totalHopsFor(6, trace)).toBe(8);
    expect(totalHopsFor(6, { ...trace, hosted: true })).toBe(10);
    expect(totalHopsFor(6, { ...trace, hosted: true, nx: true })).toBe(2);
    expect(totalHopsFor(5, trace)).toBe(8);
  });

  it('an unresolved name never emits a GET — the NX trace ends at the DNS answer', () => {
    const labels = describeSnapshot(
      snap(
        {
          hop: 2,
          method: 'GET',
          path: 'nope.example/about',
          request: 'GET nope.example/about',
          hosted: true,
          host: 'nope.example',
          resolvedPath: '/about',
          nx: true,
        },
        { dns: { ...baseDns, lookups: 1, nxAnswers: 1, cache: [] } },
      ),
    );
    expect(labels.totalHops).toBe(2);
    expect(labels.hopStatus).toBe('Hop 2/2: DNS (10.60) answers NX no record — no GET is emitted');
    const hopLabels = (hop) =>
      describeSnapshot(
        snap({
          hop,
          method: 'GET',
          path: 'nope.example/about',
          request: 'GET nope.example/about',
          hosted: true,
          host: 'nope.example',
          resolvedPath: '/about',
          nx: true,
        }),
      ).hopStatus;
    expect(hopLabels(1)).toBe('Hop 1/2: Browser (10.2) asks DNS (10.60) to resolve "nope.example"');
    // The browser viewport reads the NX answer, not a numeric status.
    const nxSnap = snap(
      { hop: 2, hosted: true, host: 'nope.example', nx: true },
      {
        dns: { ...baseDns, nxAnswers: 1, cache: [] },
        browserDisplay: {
          from: '10.60',
          to: '10.2',
          request: 'GET nope.example',
          response: 'NX no record',
          status: 'NX',
          body: 'no record',
        },
      },
    );
    expect(describeSnapshot(nxSnap).browserStatus).toBe('NX (GET nope.example)');
    expect(describeSnapshot(nxSnap).browserBody).toBe('no record');
  });
});

